function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 1500) return 'nums needs 2 to 1500 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 500)) return 'Each value is a whole number from 0 to 500.';
  return null;
}

