function longestArithSeqLength(nums) {
  const dp = [];
  let best = 2;

  for (let i = 0; i < nums.length; i++) {
    dp.push(new Map());
    for (let j = 0; j < i; j++) {
      const diff = nums[i] - nums[j];
      const length = (dp[j].get(diff) ?? 1) + 1;
      dp[i].set(diff, length);
      best = Math.max(best, length);
    }
  }
  return best;
}

