function longestArithSeqLength(nums) {
  // Fix the first two elements, then greedily take the earliest next term of the progression.
  let best = 0;
  for (let a = 0; a < nums.length; a++) {
    for (let b = a + 1; b < nums.length; b++) {
      const step = nums[b] - nums[a];
      let want = nums[b] + step;
      let count = 2;
      for (let k = b + 1; k < nums.length; k++) {
        if (nums[k] === want) {
          count++;
          want += step;
        }
      }
      if (count > best) best = count;
    }
  }
  return best;
}

