function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(2, 10);
    const top = rand() < 0.6 ? pick(1, 8) : 500;
    return [Array.from({ length: n }, () => pick(0, top))];
  }
  const n = 1500;
  const nums = Array.from({ length: n }, () => pick(0, 500));
  // Hide a long progression among the random values so the answer is not just 3 or 4.
  const terms = pick(5, 60);
  const step = pick(-8, 8);
  const start = step >= 0 ? pick(0, 500 - step * (terms - 1)) : pick(-step * (terms - 1), 500);
  const spots = new Set();
  while (spots.size < terms) spots.add(pick(0, n - 1));
  [...spots].sort((x, y) => x - y).forEach((spot, k) => { nums[spot] = start + step * k; });
  return [nums];
}
